CREATE TABLE public.ceo_report_settings (id boolean PRIMARY KEY DEFAULT true CHECK(id), enabled boolean NOT NULL DEFAULT false, paused_reason text, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE,INSERT ON public.ceo_report_settings TO authenticated; GRANT ALL ON public.ceo_report_settings TO service_role;
ALTER TABLE public.ceo_report_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Jamie manages CEO reporting" ON public.ceo_report_settings FOR ALL TO authenticated USING(public.can_manage_company_pl_access(auth.uid())) WITH CHECK(public.can_manage_company_pl_access(auth.uid()));
CREATE TABLE public.ceo_monthly_reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), period date NOT NULL UNIQUE, status text NOT NULL DEFAULT 'generating' CHECK(status IN ('generating','ready','sent','failed')), lease_until timestamptz, snapshot jsonb, commentary text, pdf_base64 text, deliveries jsonb NOT NULL DEFAULT '{}'::jsonb, error text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.ceo_monthly_reports TO authenticated; GRANT ALL ON public.ceo_monthly_reports TO service_role;
ALTER TABLE public.ceo_monthly_reports ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Jamie reads CEO reports" ON public.ceo_monthly_reports FOR SELECT TO authenticated USING(public.can_manage_company_pl_access(auth.uid()));
CREATE TABLE public.ceo_report_dispatch_tokens (token uuid PRIMARY KEY DEFAULT gen_random_uuid(), expires_at timestamptz NOT NULL DEFAULT now()+interval '10 minutes');
GRANT ALL ON public.ceo_report_dispatch_tokens TO service_role;
ALTER TABLE public.ceo_report_dispatch_tokens ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.claim_ceo_report(_period date, _retry boolean DEFAULT false) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r uuid; BEGIN INSERT INTO public.ceo_monthly_reports(period,lease_until) VALUES(_period,now()+interval '15 minutes') ON CONFLICT(period) DO UPDATE SET lease_until=now()+interval '15 minutes', updated_at=now(),status=CASE WHEN ceo_monthly_reports.pdf_base64 IS NULL THEN 'generating' ELSE 'ready' END,error=NULL WHERE (ceo_monthly_reports.lease_until IS NULL OR ceo_monthly_reports.lease_until<now()) AND ceo_monthly_reports.status<>'sent' AND (_retry OR ceo_monthly_reports.status<>'failed') RETURNING id INTO r; RETURN r; END $$;
REVOKE ALL ON FUNCTION public.claim_ceo_report(date,boolean) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.claim_ceo_report(date,boolean) TO service_role;
CREATE OR REPLACE FUNCTION public.dispatch_monthly_ceo_report() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t uuid; BEGIN IF NOT EXISTS(SELECT 1 FROM public.ceo_report_settings WHERE enabled AND paused_reason IS NULL) THEN RETURN; END IF; DELETE FROM public.ceo_report_dispatch_tokens WHERE expires_at<now(); INSERT INTO public.ceo_report_dispatch_tokens DEFAULT VALUES RETURNING token INTO t; PERFORM net.http_post(url:='https://atblyrrczwcmnyhcdkto.supabase.co/functions/v1/monthly-ceo-report',headers:=jsonb_build_object('Content-Type','application/json','x-ceo-dispatch-token',t::text),body:='{"action":"scheduled"}'::jsonb,timeout_milliseconds:=1000); END $$;
REVOKE ALL ON FUNCTION public.dispatch_monthly_ceo_report() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.dispatch_monthly_ceo_report() TO service_role;
CREATE OR REPLACE FUNCTION public.ceo_waste_summary(_cutoff date) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
WITH jobs AS (SELECT source,job_number,job_date,weight_t,movement_type,0 priority FROM public.data_hub_jobs WHERE source='midweigh' AND job_date>=date_trunc('year',_cutoff)::date-interval '1 year' AND job_date<=_cutoff UNION ALL SELECT source,job_number,job_date,weight_t,movement_type,1 FROM public.data_hub_jobs_archive WHERE source='midweigh' AND job_date>=date_trunc('year',_cutoff)::date-interval '1 year' AND job_date<=_cutoff), unique_jobs AS (SELECT DISTINCT ON(source,job_number) * FROM jobs ORDER BY source,job_number,priority), monthly AS (SELECT extract(year FROM j.job_date)::int AS yr,extract(month FROM j.job_date)::int AS mo,upper(trim(j.movement_type)) AS direction,count(*) AS jobs,sum(j.weight_t)/1000 AS tonnes FROM unique_jobs j WHERE upper(trim(j.movement_type)) IN ('INWARD','OUTWARD') AND j.weight_t IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.data_hub_void_jobs v WHERE v.source=j.source AND v.job_number=j.job_number) AND ((extract(year FROM j.job_date)=extract(year FROM _cutoff) AND j.job_date<=_cutoff) OR (extract(year FROM j.job_date)=extract(year FROM _cutoff)-1 AND j.job_date<=(_cutoff-interval '1 year')::date)) GROUP BY 1,2,3) SELECT coalesce(jsonb_agg(to_jsonb(monthly) ORDER BY yr,mo,direction),'[]'::jsonb) FROM monthly;
$$;
REVOKE ALL ON FUNCTION public.ceo_waste_summary(date) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.ceo_waste_summary(date) TO service_role;